import openpyxl, os
wb=openpyxl.load_workbook(os.environ['OUT_XLSX'])
ws=wb.active
hol={}
for r in range(2,ws.max_row+1):
    d=ws.cell(r,9).value; t=ws.cell(r,10).value
    if d is not None:
        hol[d.date()]=t
for r in range(2,ws.max_row+1):
    a=ws.cell(r,1).value
    if a is None:
        continue
    if a.date() in hol:
        ws.cell(r,5).value=hol[a.date()]
    else:
        ws.cell(r,5).value=a.strftime('%a')
wb.save(os.environ['OUT_XLSX'])
print('done')
for r in range(2,ws.max_row+1):
    print(r, ws.cell(r,1).value.date(), ws.cell(r,5).value)
